"""
Universal Configuration Package

Professional-grade configuration system for any Python application.
Provides centralized, validated, environment-specific configuration.
"""

from .core import UniversalConfig
from .config_classes import (
    DatabaseConfig,
    APIConfig,
    ShellConfig,
    LoggingConfig,
    SecurityConfig,
    PerformanceConfig,
    CacheConfig,
    TaskConfig,
)
from .loaders import ConfigLoader
from .validators import ConfigurationError

__all__ = [
    "UniversalConfig",
    "DatabaseConfig",
    "APIConfig", 
    "ShellConfig",
    "LoggingConfig",
    "SecurityConfig",
    "PerformanceConfig",
    "CacheConfig",
    "TaskConfig",
    "ConfigLoader",
    "ConfigurationError",
]

# Convenience functions for backward compatibility
def load_config(config_path=None):
    """Load configuration from file or environment."""
    if config_path:
        return ConfigLoader.from_file(config_path)
    return ConfigLoader.from_env()


def create_default_config():
    """Create default configuration."""
    return UniversalConfig.create_default()


def create_production_config(project_root=None):
    """Create production configuration."""
    return UniversalConfig.create_for_production(project_root)


def create_development_config(project_root):
    """Create development configuration."""
    return UniversalConfig.create_for_development(project_root)


def create_test_config(**overrides):
    """Create test configuration."""
    return UniversalConfig.create_for_testing(**overrides)

"""
Universal Configuration Core

Core configuration classes and constants for universal application configuration.
"""

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Dict, Optional, Union

import yaml

from .config_classes import (
    DatabaseConfig, APIConfig, ShellConfig, LoggingConfig,
    SecurityConfig, PerformanceConfig, CacheConfig, TaskConfig
)
from .validators import ConfigurationError, validate_database_config, validate_api_config, validate_logging_config


@dataclass
class UniversalConfig:
    """
    Universal configuration system for any Python application.

    Manages settings for all major components with validation,
    environment variable support, and YAML file loading.
    """

    # Environment identification
    environment: str = "production"

    # Core paths
    project_root: Path = field(default_factory=Path.cwd)
    config_file: Optional[Path] = None

    # Component configurations
    database: DatabaseConfig = field(default_factory=DatabaseConfig)
    api: APIConfig = field(default_factory=APIConfig)
    shell: ShellConfig = field(default_factory=ShellConfig)
    logging: LoggingConfig = field(default_factory=LoggingConfig)
    security: SecurityConfig = field(default_factory=SecurityConfig)
    performance: PerformanceConfig = field(default_factory=PerformanceConfig)
    cache: CacheConfig = field(default_factory=CacheConfig)
    task: TaskConfig = field(default_factory=TaskConfig)

    def __post_init__(self):
        """Validate configuration after initialization."""
        self.validate()

    def validate(self) -> None:
        """Validate configuration values."""
        errors = []

        # Environment validation
        if self.environment not in ["production", "development", "test"]:
            errors.append("environment must be one of: production, development, test")

        # Component validation
        errors.extend(validate_database_config(self.database))
        errors.extend(validate_api_config(self.api))
        errors.extend(validate_logging_config(self.logging))

        # Shell validation
        if self.shell.timeout <= 0:
            errors.append("shell.timeout must be positive")
        if self.shell.max_output_lines <= 0:
            errors.append("shell.max_output_lines must be positive")
        if self.shell.max_retries < 0:
            errors.append("shell.max_retries must be non-negative")

        # Performance validation
        if self.performance.max_concurrent_operations <= 0:
            errors.append("performance.max_concurrent_operations must be positive")
        if self.performance.max_worker_threads <= 0:
            errors.append("performance.max_worker_threads must be positive")

        # Cache validation
        if self.cache.ttl_seconds <= 0:
            errors.append("cache.ttl_seconds must be positive")
        if self.cache.max_size <= 0:
            errors.append("cache.max_size must be positive")

        # Task validation
        if self.task.max_workers <= 0:
            errors.append("task.max_workers must be positive")
        if self.task.queue_size <= 0:
            errors.append("task.queue_size must be positive")
        if self.task.retry_attempts < 0:
            errors.append("task.retry_attempts must be non-negative")

        if errors:
            raise ConfigurationError(
                "Configuration validation failed",
                config_path=str(self.config_file) if self.config_file else None,
                validation_errors=errors,
            )

    @classmethod
    def create_default(cls) -> "UniversalConfig":
        """Create default configuration."""
        return cls()

    @classmethod
    def create_for_production(cls, project_root: Optional[Path] = None) -> "UniversalConfig":
        """Create production-optimized configuration."""
        return cls(
            environment="production",
            project_root=project_root or Path.cwd(),
            logging=LoggingConfig(level="INFO", format="json"),
            api=APIConfig(debug=False, workers=4),
            performance=PerformanceConfig(
                enable_caching=True,
                max_concurrent_operations=20,
                max_worker_threads=8
            ),
        )

    @classmethod
    def create_for_development(cls, project_root: Path) -> "UniversalConfig":
        """Create development-optimized configuration."""
        return cls(
            environment="development",
            project_root=project_root,
            logging=LoggingConfig(level="DEBUG", format="console"),
            api=APIConfig(debug=True, reload=True),
            database=DatabaseConfig(echo=True),
        )

    @classmethod
    def create_for_testing(cls, **overrides) -> "UniversalConfig":
        """Create testing-optimized configuration."""
        test_config = cls(
            environment="test",
            logging=LoggingConfig(level="WARNING"),
            database=DatabaseConfig(url="sqlite:///:memory:"),
            performance=PerformanceConfig(enable_caching=False),
            cache=CacheConfig(backend="memory"),
        )

        # Apply any overrides
        for key, value in overrides.items():
            if hasattr(test_config, key):
                setattr(test_config, key, value)

        return test_config

    def to_dict(self) -> Dict[str, Any]:
        """Convert configuration to dictionary."""
        return {
            "environment": self.environment,
            "project_root": str(self.project_root),
            "config_file": str(self.config_file) if self.config_file else None,
            "database": self.database.__dict__,
            "api": self.api.__dict__,
            "shell": self.shell.__dict__,
            "logging": self.logging.__dict__,
            "security": self.security.__dict__,
            "performance": self.performance.__dict__,
            "cache": self.cache.__dict__,
            "task": self.task.__dict__,
        }

    def save_to_file(self, file_path: Union[str, Path]) -> None:
        """Save configuration to YAML file."""
        file_path = Path(file_path)

        # Create directory if it doesn't exist
        file_path.parent.mkdir(parents=True, exist_ok=True)

        with open(file_path, "w") as f:
            yaml.dump(self.to_dict(), f, default_flow_style=False, indent=2)

    @classmethod
    def load_from_file(cls, file_path: Union[str, Path]) -> "UniversalConfig":
        """Load configuration from YAML file."""
        from .loaders import ConfigLoader
        return ConfigLoader.from_file(file_path)

    @classmethod
    def load_from_env(cls) -> "UniversalConfig":
        """Load configuration from environment variables."""
        from .loaders import ConfigLoader
        return ConfigLoader.from_env()

    def get_database_url(self) -> str:
        """Get database URL with environment variable substitution."""
        url = self.database.url
        if url and "${" in url:
            # Simple environment variable substitution
            import re
            def replace_env_var(match):
                var_name = match.group(1)
                return os.getenv(var_name, match.group(0))
            url = re.sub(r'\$\{([^}]+)\}', replace_env_var, url)
        return url

    def is_production(self) -> bool:
        """Check if running in production mode."""
        return self.environment == "production"

    def is_development(self) -> bool:
        """Check if running in development mode."""
        return self.environment == "development"

    def is_test(self) -> bool:
        """Check if running in test mode."""
        return self.environment == "test"

"""
Universal Configuration Validation

Configuration validation utilities and error definitions.
"""

from typing import Any, Dict, List, Optional


class ConfigurationError(Exception):
    """Raised when configuration validation fails or configuration cannot be loaded."""

    def __init__(
        self,
        message: str,
        config_path: Optional[str] = None,
        validation_errors: Optional[List[str]] = None,
        **kwargs,
    ):
        super().__init__(message)
        self.message = message
        self.config_path = config_path
        self.validation_errors = validation_errors or []

    def to_dict(self) -> Dict[str, Any]:
        """Convert error to dictionary for structured logging."""
        return {
            "error_type": self.__class__.__name__,
            "message": self.message,
            "config_path": self.config_path,
            "validation_errors": self.validation_errors,
        }


def validate_database_config(config: DatabaseConfig) -> List[str]:
    """Validate database configuration."""
    errors = []

    if not config.url:
        errors.append("Database URL is required")

    if config.pool_size <= 0:
        errors.append("Database pool_size must be positive")

    if config.max_overflow < 0:
        errors.append("Database max_overflow cannot be negative")

    return errors


def validate_api_config(config: APIConfig) -> List[str]:
    """Validate API configuration."""
    errors = []

    if config.port < 1 or config.port > 65535:
        errors.append("API port must be between 1 and 65535")

    if config.workers < 1:
        errors.append("API workers must be at least 1")

    return errors


def validate_logging_config(config: LoggingConfig) -> List[str]:
    """Validate logging configuration."""
    errors = []

    valid_levels = ["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"]
    if config.level.upper() not in valid_levels:
        errors.append(f"Log level must be one of: {valid_levels}")

    valid_formats = ["json", "console", "structured"]
    if config.format not in valid_formats:
        errors.append(f"Log format must be one of: {valid_formats}")

    if config.max_file_size <= 0:
        errors.append("Log max_file_size must be positive")

    return errors

"""Action execution for explore agent."""

from typing import Any, Dict

from ...agent_api import ConstitutionalViolationError
from ...phoenix_logging import get_logger


_logger = get_logger("phoenix.explore_agent.actions")


class ActionExecutor:
    """Executes individual steps in the exploration process."""

    def __init__(self, api: Any):
        if api is None:
            raise ValueError("Agent API instance is required")
        self._api = api

    def execute_step(self, step: str) -> Dict[str, Any]:
        """Execute a single step via AgentAPI tools."""
        try:
            # Normalize step: remove backticks, trailing pipes/descriptions
            step = step.strip()
            if step.startswith("`") and step.endswith("`"):
                step = step[1:-1].strip()
            # Remove pipe-delimited description
            if "|" in step:
                step = step.split("|")[0].strip()
            # Remove trailing punctuation
            step = step.rstrip(".,;:")

            action, _, remainder = step.partition(":")
            action = action.lower().strip()
            remainder = remainder.strip()

            if action == "filesystem":
                return self._execute_filesystem_step(remainder)
            if action in {"system", "shell"}:
                return self._execute_system_step(remainder)

            # Fallback heuristics for natural language steps
            if "list" in step.lower():
                return self._execute_filesystem_step(f"list {remainder or '.'}")
            if "read" in step.lower():
                return self._execute_filesystem_step(f"read {remainder}")
            if "shell" in step.lower() or "run" in step.lower():
                command = remainder or step
                return self._execute_system_step(command)

            return {
                "success": False,
                "detail": f"Unsupported step format: {step}",
            }

        except ConstitutionalViolationError as exc:
            _logger.warning(
                "Constitutional violation during execution",
                step=step,
                error=str(exc),
            )
            return {
                "success": False,
                "detail": f"Constitutional violation: {exc.message}",
                "violation": exc.to_dict(),
            }
        except Exception as exc:  # Broad to keep agent resilient in MVP
            _logger.warning(
                "Execution step failed",
                step=step,
                error=str(exc),
            )
            return {
                "success": False,
                "detail": f"Execution error: {exc}",
            }

    def _execute_filesystem_step(self, instruction: str) -> Dict[str, Any]:
        fs_api = getattr(self._api, "filesystem", None)
        if fs_api is None:
            return {"success": False, "detail": "Filesystem API is unavailable"}

        verb, _, target = instruction.partition(" ")
        verb = verb.lower().strip()
        target = target.strip() or "."

        try:
            if verb == "list":
                listing = fs_api.list_directory(target)
                return {
                    "success": True,
                    "detail": f"Listed {target}: {listing}",
                    "data": listing,
                    "type": "filesystem.list_directory",
                }
            if verb == "read":
                # Check if target is a directory and suggest list instead
                import os

                if os.path.isdir(target):
                    _logger.info(
                        "Cannot read directory, using list instead",
                        target=target,
                    )
                    listing = fs_api.list_directory(target)
                    return {
                        "success": True,
                        "detail": f"Cannot read directory {target}, listed instead: {listing}",
                        "data": listing,
                        "type": "filesystem.list_directory",
                    }
                content = fs_api.read(target)
                return {
                    "success": True,
                    "detail": f"Read {target}: {content}",
                    "data": content,
                    "type": "filesystem.read",
                }
            if verb == "write":
                path, _, content = target.partition(" ")
                fs_api.write(path, content)
                return {
                    "success": True,
                    "detail": f"Wrote to {path}",
                    "type": "filesystem.write",
                }
        except FileNotFoundError as exc:
            _logger.info(
                "Filesystem target not found",
                verb=verb,
                target=target,
                error=str(exc),
            )
            return {
                "success": False,
                "detail": f"Filesystem target not found: {target}",
                "error": "file_not_found",
            }
        except OSError as exc:
            _logger.warning(
                "Filesystem operation failed",
                verb=verb,
                target=target,
                error=str(exc),
            )
            return {
                "success": False,
                "detail": f"Filesystem error for {target}: {exc}",
                "error": "filesystem_error",
            }

        return {"success": False, "detail": f"Unknown filesystem verb: {verb}"}

    def _execute_system_step(self, instruction: str) -> Dict[str, Any]:
        system_api = getattr(self._api, "system", None)
        if system_api is None:
            return {"success": False, "detail": "System API is unavailable"}

        command = instruction.strip()
        if not command:
            return {"success": False, "detail": "Shell command is empty"}

        try:
            result = system_api.run_shell_command(command)
        except TimeoutError as exc:
            _logger.warning(
                "Shell command timed out",
                command=command,
                error=str(exc),
            )
            return {
                "success": False,
                "detail": f"Command timeout: {command}",
                "error": "timeout",
            }
        except Exception as exc:
            _logger.warning(
                "Shell command failed",
                command=command,
                error=str(exc),
            )
            return {
                "success": False,
                "detail": f"Command error: {exc}",
                "error": "command_error",
            }

        success = result.get("exit_code", 1) == 0
        return {
            "success": success,
            "detail": f"Command `{command}` exited with {result.get('exit_code')}",
            "data": result,
            "type": "system.run_shell_command",
        }


__all__ = ["ActionExecutor"]

"""Embedding and RAG utilities for explore agent."""

import hashlib
import math
import os
import time
from typing import Any, Callable, Dict, Iterable, List, Optional, Sequence


Vector = Sequence[float]

_ENABLE_LANCEDB = os.environ.get("EXPLORE_AGENT_ENABLE_LANCEDB") == "1"
_ENABLE_SENTENCE_TRANSFORMER = (
    os.environ.get("EXPLORE_AGENT_ENABLE_SENTENCE_TRANSFORMER") == "1"
)

MAX_TEMP_RAG_ENTRIES = 1_000


def _normalize_vector(values: Iterable[float]) -> List[float]:
    vector = [float(v) for v in values]
    norm = math.sqrt(sum(v * v for v in vector)) or 1.0
    return [v / norm for v in vector]


def _hash_embedding(text: str, dims: int = 16) -> List[float]:
    """Deterministic fallback embedding that does not require external deps."""
    digest = hashlib.sha256(text.encode("utf-8")).digest()
    chunk_size = max(1, len(digest) // dims)
    values = []
    for idx in range(dims):
        start = idx * chunk_size
        chunk = digest[start : start + chunk_size] or digest
        values.append(float(int.from_bytes(chunk, "big")))
    return _normalize_vector(values)


def create_embedding_fn() -> Callable[[str], Vector]:
    """Prefer SentenceTransformer embeddings, fallback to hash-based."""
    if not _ENABLE_SENTENCE_TRANSFORMER:
        return _hash_embedding

    try:  # pragma: no cover - dependent on runtime availability
        from sentence_transformers import SentenceTransformer  # type: ignore

        model = SentenceTransformer("all-MiniLM-L6-v2")
    except Exception:
        return _hash_embedding

    def embed(text: str) -> Vector:
        vector = model.encode([text])[0]
        return _normalize_vector(vector.tolist())

    return embed


class _TempRAGStore:
    """In-memory similarity store with optional LanceDB backing."""

    def __init__(
        self,
        embed_fn: Callable[[str], Vector],
        similarity_threshold: float,
        max_entries: int = MAX_TEMP_RAG_ENTRIES,
    ):
        self._embed = embed_fn
        self._threshold = similarity_threshold
        self.backend = "fallback"
        self._entries: List[Dict[str, Any]] = []
        self._db = None
        self._table = None
        self._max_entries = max(1, max_entries)
        if _ENABLE_LANCEDB:
            self.backend = "lancedb"
            self._initialise_lancedb()

    def _initialise_lancedb(self) -> None:
        """Create an in-memory LanceDB table if dependency is available."""
        try:
            import lancedb  # type: ignore

            self._db = lancedb.connect(":memory:")
            # Lazy table creation; we only add rows via add()
            self._table = self._db.create_table(
                "explore_findings",
                data=[],
                mode="overwrite",
            )
        except Exception:  # pragma: no cover - LanceDB optional and heavy
            self.backend = "fallback"
            self._db = None
            self._table = None

    def reset(self) -> None:
        self._entries.clear()
        if self.backend == "lancedb" and self._db is not None:
            try:  # pragma: no cover - optional dependency
                self._table = self._db.create_table(
                    "explore_findings",
                    data=[],
                    mode="overwrite",
                )
            except Exception:
                self.backend = "fallback"
                self._table = None

    def add(self, text: str, metadata: Optional[Dict[str, Any]] = None) -> None:
        if not text.strip():
            return
        try:
            vector = self._embed(text)
        except Exception:
            return
        payload = {
            "text": text,
            "vector": vector,
            "metadata": metadata or {},
            "timestamp": time.time(),
        }
        self._entries.append(payload)
        if len(self._entries) > self._max_entries:
            self._entries.pop(0)

        if self.backend == "lancedb" and self._table is not None:
            try:  # pragma: no cover - exercised when dependency available
                self._table.add([payload])
            except Exception:
                # If the LanceDB row fails, we still have the fallback store.
                self.backend = "fallback"

    def query(self, text: str, k: int = 3) -> List[Dict[str, Any]]:
        if not text.strip():
            return []

        try:
            vector = self._embed(text)
        except Exception:
            return []
        matches: List[Dict[str, Any]] = []

        for entry in self._entries:
            similarity = self._cosine_similarity(vector, entry["vector"])
            if similarity >= self._threshold:
                matches.append(
                    {
                        "text": entry["text"],
                        "metadata": entry["metadata"],
                        "similarity": similarity,
                    }
                )

        matches.sort(key=lambda item: item["similarity"], reverse=True)
        return matches[:k]

    @staticmethod
    def _cosine_similarity(lhs: Vector, rhs: Vector) -> float:
        numerator = sum(float(x) * float(y) for x, y in zip(lhs, rhs, strict=False))
        lhs_norm = math.sqrt(sum(float(x) * float(x) for x in lhs)) or 1.0
        rhs_norm = math.sqrt(sum(float(y) * float(y) for y in rhs)) or 1.0
        return numerator / (lhs_norm * rhs_norm)

    @property
    def similarity_threshold(self) -> float:
        return self._threshold


__all__ = [
    "Vector",
    "_TempRAGStore",
    "_normalize_vector",
    "_hash_embedding",
    "create_embedding_fn",
    "MAX_TEMP_RAG_ENTRIES",
]

"""Analysis handler for explore agent actions."""

from typing import Any, Dict

from ....phoenix_logging import get_logger
from ..tool_abstractions import CodeAnalyzer


_logger = get_logger("phoenix.explore_agent.handlers.analysis")


class AnalysisHandler:
    """Handles code analysis operations with multi-analysis support."""

    def __init__(self, api: Any):
        """Initialize analysis handler.

        Args:
            api: Agent API instance
        """
        if api is None:
            raise ValueError("Agent API instance is required")
        self._api = api
        self._code_analyzer = CodeAnalyzer(api)

    def analyze_python(
        self, file_path: str, analysis_type: str = "all"
    ) -> Dict[str, Any]:
        """Analyze Python file combining multiple analysis types.

        Args:
            file_path: Path to Python file to analyze
            analysis_type: Type of analysis (functions, classes, imports, all)

        Returns:
            Dict with success/detail/data containing combined results
        """
        result = {}

        if analysis_type in ("functions", "all"):
            result.update(self._code_analyzer.find_functions(file_path))

        if analysis_type in ("classes", "all"):
            classes_result = self._code_analyzer.find_classes(file_path)
            if classes_result["success"]:
                result["classes"] = classes_result.get("classes", [])

        if analysis_type in ("imports", "all"):
            imports_result = self._code_analyzer.find_imports(file_path)
            if imports_result["success"]:
                result["imports"] = imports_result.get("imports", [])

        # Return combined results
        if result:
            return {
                "success": True,
                "data": result,
                "detail": f"Analyzed {file_path}: {len(result.get('classes', []))} classes found",
                **result,
            }
        else:
            return {
                "success": False,
                "data": [],
                "detail": f"Analysis type '{analysis_type}' not recognized",
                "error": "invalid_analysis_type",
            }

"""Filesystem handler for explore agent actions."""

import os
from typing import Any, Dict

from ....phoenix_logging import get_logger
from ..tool_abstractions import FileFinder


_logger = get_logger("phoenix.explore_agent.handlers.filesystem")


class FilesystemHandler:
    """Handles filesystem operations (list and read) with API validation."""

    def __init__(self, api: Any):
        """Initialize filesystem handler.

        Args:
            api: Agent API instance
        """
        if api is None:
            raise ValueError("Agent API instance is required")
        self._api = api
        self._file_finder = FileFinder(api)

    def list(self, path: str = ".") -> Dict[str, Any]:
        """List directory contents with API validation.

        Args:
            path: Directory path to list

        Returns:
            Dict with success/detail/data
        """
        fs_api = getattr(self._api, "filesystem", None)
        if fs_api is None:
            return {
                "success": False,
                "detail": "Filesystem API is unavailable",
                "error": "api_unavailable",
            }

        try:
            listing = fs_api.list_directory(path)
            return {
                "success": True,
                "detail": f"Listed {path}",
                "data": listing,
                "type": "filesystem.list_directory",
            }
        except FileNotFoundError:
            _logger.info("Filesystem target not found", verb="list", target=path)
            return {
                "success": False,
                "detail": f"Filesystem target not found: {path}",
                "error": "file_not_found",
            }
        except OSError as exc:
            _logger.warning(
                "Filesystem operation failed", verb="list", target=path, error=str(exc)
            )
            return {
                "success": False,
                "detail": f"Filesystem error for {path}: {exc}",
                "error": "filesystem_error",
            }

    def read(self, path: str) -> Dict[str, Any]:
        """Read file contents with directory detection.

        Automatically lists directory if path points to a directory.

        Args:
            path: File path to read

        Returns:
            Dict with success/detail/data
        """
        fs_api = getattr(self._api, "filesystem", None)
        if fs_api is None:
            return {
                "success": False,
                "detail": "Filesystem API is unavailable",
                "error": "api_unavailable",
            }

        if not path:
            return {
                "success": False,
                "detail": "Path is required for read operation",
                "error": "missing_argument",
            }

        try:
            # Check if it's a directory - if so, list it instead
            if os.path.isdir(path):
                _logger.info("Cannot read directory, using list instead", target=path)
                return self.list(path)

            content = fs_api.read(path)
            return {
                "success": True,
                "detail": f"Read {path}",
                "data": content,
                "type": "filesystem.read",
            }
        except FileNotFoundError:
            _logger.info("Filesystem target not found", verb="read", target=path)
            return {
                "success": False,
                "detail": f"Filesystem target not found: {path}",
                "error": "file_not_found",
            }
        except OSError as exc:
            _logger.warning(
                "Filesystem operation failed", verb="read", target=path, error=str(exc)
            )
            return {
                "success": False,
                "detail": f"Filesystem error for {path}: {exc}",
                "error": "filesystem_error",
            }

"""Shell handler for explore agent actions."""

from typing import Any, Dict

from ....phoenix_logging import get_logger


_logger = get_logger("phoenix.explore_agent.handlers.shell")


class ShellHandler:
    """Handles shell command execution with API validation."""

    def __init__(self, api: Any):
        """Initialize shell handler.

        Args:
            api: Agent API instance
        """
        if api is None:
            raise ValueError("Agent API instance is required")
        self._api = api

    def run(self, command: str) -> Dict[str, Any]:
        """Run shell command with API validation.

        Args:
            command: Shell command to execute

        Returns:
            Dict with success/detail/data
        """
        system_api = getattr(self._api, "system", None)
        if system_api is None:
            return {
                "success": False,
                "detail": "System API is unavailable",
                "error": "api_unavailable",
            }

        if not command:
            return {
                "success": False,
                "detail": "Shell command is empty",
                "error": "missing_argument",
            }

        try:
            result = system_api.run_shell_command(command)
            success = result.get("exit_code", 1) == 0
            return {
                "success": success,
                "detail": f"Command exited with {result.get('exit_code')}",
                "data": result,
                "type": "system.run_shell_command",
            }
        except TimeoutError:
            _logger.warning("Shell command timed out", command=command)
            return {
                "success": False,
                "detail": f"Command timeout: {command}",
                "error": "timeout",
            }
        except Exception as exc:
            _logger.warning("Shell command failed", command=command, error=str(exc))
            return {
                "success": False,
                "detail": f"Command error: {exc}",
                "error": "command_error",
            }

"""Intelligent tool abstractions for explore agent.

Instead of giving the LLM raw shell_run, we provide high-level "Baustein" tools
that are:
- Fast (no subprocess overhead for common operations)
- Safe (validation built-in, no injection possible)
- Composable (can be chained together)
- Semantic (LLM understands the intent, not the syntax)
"""

from pathlib import Path
from typing import Any, Dict, List, Optional


class ToolAbstraction:
    """Base class for intelligent tool abstractions."""

    def __init__(self, api: Any):
        self._api = api


class FileFinder(ToolAbstraction):
    """Find files matching patterns - like 'find' but safe and semantic."""

    # Standard ignore patterns for find command - prevents searching irrelevant directories
    DEFAULT_IGNORE_DIRS = [
        ".git",
        "venv",
        ".venv",
        "env",
        ".env",
        "__pycache__",
        ".pytest_cache",
        ".mypy_cache",
        "node_modules",
        ".tox",
        "dist",
        "build",
        "*.egg-info",
    ]

    def search(
        self,
        directory: str = ".",
        name_pattern: str = "*",
        file_type: Optional[str] = None,
    ) -> Dict[str, Any]:
        """
        Find files matching a pattern using native Python (fast, safe).

        Args:
            directory: Directory to search in
            name_pattern: Filename pattern (e.g., "*.py", "test_*.py")
            file_type: Optional type filter ("f"=file, "d"=dir)

        Returns:
            Dict with success status and list of found files
        """
        try:
            import os
            from fnmatch import fnmatch

            base_path = Path(directory).resolve()
            if not base_path.exists():
                return {
                    "success": False,
                    "detail": f"Directory not found: {directory}",
                    "files": [],
                    "data": [],
                }

            files = []

            # Walk directory tree with native Python (os.walk for compatibility)
            for root, dirs, filenames in os.walk(base_path):
                root_path = Path(root)

                # Filter out ignored directories IN-PLACE to prevent traversal
                dirs[:] = [
                    d
                    for d in dirs
                    if not any(
                        fnmatch(d, pattern) for pattern in self.DEFAULT_IGNORE_DIRS
                    )
                ]

                # Collect matching items based on type filter
                if file_type == "d":
                    # Looking for directories
                    for dirname in dirs:
                        if fnmatch(dirname, name_pattern):
                            files.append(str(root_path / dirname))
                else:
                    # Looking for files (default)
                    for filename in filenames:
                        if fnmatch(filename, name_pattern):
                            files.append(str(root_path / filename))

            return {
                "success": True,
                "files": files,
                "data": files,
                "count": len(files),
                "detail": f"Found {len(files)} file(s)",
            }
        except Exception as e:
            return {"success": False, "detail": str(e), "files": [], "data": []}


class ContentSearcher(ToolAbstraction):
    """Search file content - like 'grep' but semantic."""

    # Standard ignore patterns for grep - prevents searching irrelevant files
    DEFAULT_IGNORE_PATTERNS = [
        ".git",
        "venv",
        ".venv",
        "env",
        ".env",
        "__pycache__",
        ".pytest_cache",
        ".mypy_cache",
        "node_modules",
        ".tox",
        "dist",
        "build",
        "*.egg-info",
        ".coverage",
        "*.pyc",
    ]

    def search(
        self,
        pattern: str,
        files: Optional[List[str]] = None,
        directory: str = ".",
        regex: bool = True,
        case_sensitive: bool = False,
    ) -> Dict[str, Any]:
        """
        Search for pattern in files using native Python (fast, safe).

        Args:
            pattern: Text or regex pattern to search for
            files: Specific files to search (if None, searches directory)
            directory: Directory to search if files is None
            regex: Whether pattern is regex or literal
            case_sensitive: Case sensitivity

        Returns:
            Dict with matches
        """
        try:
            import os
            import re
            from fnmatch import fnmatch

            # Compile pattern
            flags = 0 if case_sensitive else re.IGNORECASE
            if regex:
                pattern_re = re.compile(pattern, flags)
            else:
                pattern_re = re.compile(re.escape(pattern), flags)

            matches = []

            # Determine which files to search
            if files:
                search_files = [Path(f) for f in files if Path(f).is_file()]
            else:
                # Walk directory for text files (using os.walk for compatibility)
                search_files = []
                base_path = Path(directory).resolve()
                if base_path.exists():
                    for root, dirs, filenames in os.walk(base_path):
                        root_path = Path(root)

                        # Skip ignored directories IN-PLACE
                        dirs[:] = [
                            d
                            for d in dirs
                            if not any(
                                fnmatch(d, pat) for pat in self.DEFAULT_IGNORE_PATTERNS
                            )
                        ]

                        for filename in filenames:
                            # Skip ignored file patterns
                            if any(
                                fnmatch(filename, pat)
                                for pat in self.DEFAULT_IGNORE_PATTERNS
                            ):
                                continue
                            search_files.append(root_path / filename)

            # Search each file
            for file_path in search_files:
                try:
                    with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
                        for line_num, line in enumerate(f, 1):
                            if pattern_re.search(line):
                                matches.append(
                                    f"{file_path}:{line_num}:{line.rstrip()}"
                                )
                except (OSError, UnicodeDecodeError):
                    # Skip files that can't be read
                    continue

            return {
                "success": True,
                "matches": matches,
                "data": matches,
                "count": len(matches),
                "detail": f"Found {len(matches)} match(es)",
            }
        except Exception as e:
            return {"success": False, "detail": str(e), "matches": [], "data": []}


class CodeAnalyzer(ToolAbstraction):
    """Analyze code structure - Python AST based."""

    def find_functions(self, file_path: str) -> Dict[str, Any]:
        """Find all function definitions in a Python file."""
        try:
            import ast

            with open(file_path, "r", encoding="utf-8") as f:
                tree = ast.parse(f.read())

            functions = []
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    functions.append(
                        {
                            "name": node.name,
                            "line": node.lineno,
                            "docstring": ast.get_docstring(node),
                        }
                    )

            return {
                "success": True,
                "functions": functions,
                "data": functions,  # ← Make data available
                "count": len(functions),
                "detail": f"Found {len(functions)} function(s)",
            }
        except Exception as e:
            return {"success": False, "detail": str(e), "functions": [], "data": []}

    def find_classes(self, file_path: str) -> Dict[str, Any]:
        """Find all class definitions in a Python file."""
        try:
            import ast

            with open(file_path, "r", encoding="utf-8") as f:
                tree = ast.parse(f.read())

            classes = []
            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef):
                    classes.append(
                        {
                            "name": node.name,
                            "line": node.lineno,
                            "docstring": ast.get_docstring(node),
                            "methods": [
                                m.name
                                for m in node.body
                                if isinstance(m, ast.FunctionDef)
                            ],
                        }
                    )

            return {
                "success": True,
                "classes": classes,
                "data": classes,  # ← Make data available
                "count": len(classes),
                "detail": f"Found {len(classes)} class(es)",
            }
        except Exception as e:
            return {"success": False, "detail": str(e), "classes": [], "data": []}

    def find_imports(self, file_path: str) -> Dict[str, Any]:
        """Find all imports in a Python file."""
        try:
            import ast

            with open(file_path, "r", encoding="utf-8") as f:
                tree = ast.parse(f.read())

            imports = []
            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        imports.append({"module": alias.name, "type": "import"})
                elif isinstance(node, ast.ImportFrom):
                    module = node.module or ""
                    for alias in node.names:
                        imports.append(
                            {
                                "module": f"{module}.{alias.name}",
                                "type": "from_import",
                            }
                        )

            return {
                "success": True,
                "imports": imports,
                "data": imports,  # ← Make data available
                "count": len(imports),
                "detail": f"Found {len(imports)} import(s)",
            }
        except Exception as e:
            return {"success": False, "detail": str(e), "imports": [], "data": []}


class DirectoryAnalyzer(ToolAbstraction):
    """Composite tool: Analyze entire directory without LLM iteration.

    This is the key solution to "Context Explosion". Instead of:
    1. LLM calls find_files (returns 30 files)
    2. LLM loops 30 times, calling analyze_python_file for each
    3. Context grows exponentially

    We do:
    1. LLM calls analyze_directory once
    2. Python loops internally 30 times
    3. Context grows only by the summary
    """

    def analyze(
        self,
        directory: str = ".",
        pattern: str = "*.py",
        file_type: str = "f",
    ) -> Dict[str, Any]:
        """
        Analyze all files in a directory matching pattern.
        Returns consolidated statistics, not individual results.

        Args:
            directory: Directory to analyze
            pattern: File pattern to match (e.g., "*.py")
            file_type: Type filter ("f"=file, "d"=dir)

        Returns:
            Dict with consolidated analysis results
        """
        try:
            # Step 1: Find all files matching pattern (in Python, not via LLM)
            finder = FileFinder(self._api)
            find_result = finder.search(
                directory=directory,
                name_pattern=pattern,
                file_type=file_type,
            )

            if not find_result["success"]:
                return {
                    "success": False,
                    "detail": find_result["detail"],
                    "data": None,
                }

            files = find_result["files"]

            # Step 2: Analyze each file (in Python loop, not via LLM)
            analyzer = CodeAnalyzer(self._api)
            total_classes = 0
            total_functions = 0
            total_imports = 0
            files_analyzed = 0
            errors = []

            for file_path in files:
                try:
                    if not Path(file_path).exists():
                        continue

                    classes_result = analyzer.find_classes(file_path)
                    funcs_result = analyzer.find_functions(file_path)
                    imports_result = analyzer.find_imports(file_path)

                    if classes_result["success"]:
                        total_classes += classes_result["count"]
                    if funcs_result["success"]:
                        total_functions += funcs_result["count"]
                    if imports_result["success"]:
                        total_imports += imports_result["count"]

                    files_analyzed += 1

                except Exception as e:
                    errors.append(f"{file_path}: {str(e)}")

            # Step 3: Return consolidated summary (not individual results)
            summary = {
                "success": True,
                "directory": directory,
                "pattern": pattern,
                "files_found": len(files),
                "files_analyzed": files_analyzed,
                "total_classes": total_classes,
                "total_functions": total_functions,
                "total_imports": total_imports,
                "errors": errors,
                "detail": (
                    f"Analyzed {files_analyzed}/{len(files)} files: "
                    f"{total_classes} classes, {total_functions} functions, "
                    f"{total_imports} imports"
                ),
                "data": {
                    "total_classes": total_classes,
                    "total_functions": total_functions,
                    "total_imports": total_imports,
                    "files_analyzed": files_analyzed,
                },
            }

            return summary

        except Exception as e:
            return {"success": False, "detail": str(e), "data": None}

    def search_codebase(
        self,
        directory: str = ".",
        pattern: str = "*",
        content_pattern: str = None,
        file_type: str = "f",
    ) -> Dict[str, Any]:
        """
        Find files matching pattern, optionally filtering by content.
        Returns consolidated results.

        Args:
            directory: Directory to search
            pattern: File name pattern
            content_pattern: Optional content regex to filter files
            file_type: Type filter

        Returns:
            Dict with consolidated search results
        """
        try:
            finder = FileFinder(self._api)
            find_result = finder.search(
                directory=directory,
                name_pattern=pattern,
                file_type=file_type,
            )

            if not find_result["success"]:
                return {
                    "success": False,
                    "detail": find_result["detail"],
                    "data": None,
                }

            files = find_result["files"]

            # If no content pattern, just return the files
            if not content_pattern:
                return {
                    "success": True,
                    "files_found": len(files),
                    "files": files,
                    "data": {
                        "files_found": len(files),
                        "files": files[:100],  # Limit to 100 for context
                    },
                    "detail": f"Found {len(files)} file(s)",
                }

            # If content pattern specified, filter files by content
            searcher = ContentSearcher(self._api)
            matching_files = []

            for file_path in files:
                search_result = searcher.search(
                    pattern=content_pattern,
                    files=[file_path],
                    regex=True,
                )
                if search_result["success"] and search_result["matches"]:
                    matching_files.append(
                        {
                            "file": file_path,
                            "matches": len(search_result["matches"]),
                        }
                    )

            return {
                "success": True,
                "files_found": len(files),
                "files_matching_content": len(matching_files),
                "matching_files": matching_files,
                "data": {
                    "files_found": len(files),
                    "files_matching_content": len(matching_files),
                    "matching_files": matching_files[:50],  # Limit for context
                },
                "detail": (
                    f"Found {len(matching_files)}/{len(files)} file(s) matching content"
                ),
            }

        except Exception as e:
            return {"success": False, "detail": str(e), "data": None}

